{"title":"Daikin RM4 temperature and humidity","type":"vega","params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Daikin RM4 temperature and humidity",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "hap-daikin-sensors-*",
      "body": {
        "size": 10000,
        "_source": ["@timestamp", "temperature_c", "humidity_percent", "accessory_name", "rm4_host", "rm4_mac"],
        "sort": [{"@timestamp": "asc"}]
      }
    },
    "format": {"property": "hits.hits"}
  },
  "transform": [
    {"calculate": "toDate(datum._source['@timestamp'])", "as": "time"},
    {"calculate": "datum._source.temperature_c", "as": "temperature_c"},
    {"calculate": "datum._source.humidity_percent", "as": "humidity_percent"},
    {"fold": ["temperature_c", "humidity_percent"], "as": ["metric", "value"]},
    {"filter": "datum.value != null"},
    {"calculate": "datum.metric == 'temperature_c' ? 'Temperature C' : 'Humidity %'", "as": "label"}
  ],
  "mark": {"type": "line", "point": true},
  "encoding": {
    "x": {"field": "time", "type": "temporal", "title": "Time"},
    "y": {"field": "value", "type": "quantitative", "title": "Value"},
    "color": {"field": "label", "type": "nominal", "title": "Metric"},
    "tooltip": [
      {"field": "time", "type": "temporal", "title": "Time"},
      {"field": "label", "type": "nominal", "title": "Metric"},
      {"field": "value", "type": "quantitative", "title": "Value"}
    ]
  }
}"}}
